function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 4 || nums.length > 10000) return 'nums needs 4 to 10000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value is an integer from 1 to 10000.';
  return null;
}

