function maxProductDifference(nums) {
  // Try every ordered choice of four distinct indices.
  let best = -Infinity;
  const n = nums.length;
  for (let w = 0; w < n; w++)
    for (let x = 0; x < n; x++)
      for (let y = 0; y < n; y++)
        for (let z = 0; z < n; z++) {
          if (new Set([w, x, y, z]).size < 4) continue;
          best = Math.max(best, nums[w] * nums[x] - nums[y] * nums[z]);
        }
  return best;
}

